import test from 'node:test';import assert from 'node:assert/strict';
import {elevatorCast,elevatorDecks,elevatorOrders,elevatorStages,normalizeElevator,elevatorObjective,elevatorView,elevatorAction,elevatorArtKeys,elevatorArt} from '../src/elevator.js';import {objects,materials} from '../src/data.js';import {zones} from '../src/zones.js';import {pathfind} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';import {chapterAvailable,chapterAction,chapterCanVisit,chapterNext,normalizeChapter} from '../src/adventures.js';
function finished(){let s=normalizeElevator();for(let i=0;i<6;i++){for(const id of elevatorOrders[i])s=elevatorAction(s,'science:'+id).elevator;s=elevatorAction(s,'rescue').elevator;s=elevatorAction(s,'next').elevator;}for(let i=0;i<4;i++)s=elevatorAction(s,'boss:'+i).elevator;return s;}
test('five starring astronauts and Lucas supporting preserve existing roster specialties',()=>{assert.deepEqual(elevatorCast,[0,1,3,4,2]);assert.match(elevatorView(normalizeElevator()).text,/2063/);assert.match(elevatorView(normalizeElevator(),'threat').text,/mantis-like/);assert.match(elevatorDecks[5].inspect,/spectrometer.*mixture.*separate gauge.*pressure/);});
test('six floor systems require ordered operations, rescue and lift progression without consuming progress on other choices',()=>{let s=normalizeElevator();for(let i=0;i<6;i++){assert.equal(s.deck,i);assert.equal(elevatorAction(s,'next').elevator.deck,i);assert.equal(elevatorAction(s,'rescue').elevator.rescued[i],false);for(const id of elevatorOrders[i]){const before=structuredClone(s),bad=elevatorAction(s,'science:unrelated');assert.deepEqual(bad.elevator,before);assert.match(bad.message,/Nothing is lost/);s=elevatorAction(s,'science:'+id).elevator;}assert.match(elevatorObjective(s),/Free the people/);s=elevatorAction(s,'rescue').elevator;assert.ok(s.rescued[i]);s=elevatorAction(s,'next').elevator;}assert.equal(s.deck,6);});
test('Zuglu has four player-paced phases, no skipping or timed failure and a tick-ship escape',()=>{let s=finished();assert.ok(s.resolved);assert.match(elevatorView(s,'finale').text,/Zuglu! The tick ship! We leave now/);assert.match(elevatorView(s,'finale').text,/Everyone is safe/);s={...s,boss:0,resolved:false};assert.equal(elevatorAction(s,'boss:3').elevator.boss,0);for(let i=0;i<4;i++){assert.equal(s.boss,i);s=elevatorAction(s,'boss:'+i).elevator;}assert.ok(s.resolved);assert.equal(elevatorAction(s,'moon').travel,'moon');});
test('save normalization bounds decks and partial progress; replay leaves other records outside the elevator state',()=>{assert.equal(normalizeElevator({deck:6,boss:4,rescued:Array(6).fill(true)}).deck,0);const s=finished(),copy=normalizeElevator(JSON.parse(JSON.stringify(s)));assert.deepEqual(copy,s);const replay=elevatorAction(s,'restart');assert.equal(replay.elevator.deck,0);assert.equal(replay.elevator.resolved,false);assert.equal(replay.travel,'elevator');});
test('Moon pursuit follows elevator completion in Guided, while Explore and legacy in-progress Moon saves stay available',()=>{let c=normalizeChapter({rocketReady:true});assert.equal(chapterAvailable('guided',c,true),false);c.elevatorCleared=finished().resolved;assert.ok(chapterAvailable('guided',c,true));assert.equal(chapterAvailable('guided',c,false),false);assert.equal(chapterNext(c).zone,'chapterMoon');assert.equal(chapterAction(c,'start','guided',true).travel,'chapterMoon');assert.ok(chapterCanVisit('chapterMoon','guided',c,true));assert.equal(c.station,false);assert.equal(chapterAction(c,'earth-visit','guided',true).travel,'chapterEarth');assert.equal(chapterAction(c,'hint','guided',true,'chapterEarth').travel,'chapterEarth-quartz');assert.ok(chapterAvailable('guided',normalizeChapter({started:true,rocketReady:true}),true));assert.ok(chapterAvailable('explore',normalizeChapter(),false));});
test('all story pages fit native buttons and native text region, with distinct diagrams for changed systems',()=>{const full=finished();for(const state of [normalizeElevator(),full])for(let deck=0;deck<7;deck++){const s={...full,deck,boss:state.boss,resolved:state.resolved,progress:state.progress,rescued:full.rescued};for(const page of ['intro','threat','system','rescue','inspect','hint','next','tick-ship','restart','finale']){const v=elevatorView(s,page);assert.ok(v.actions.length+2<=6,page);assert.ok(elevatorArtKeys.includes(v.art),v.art);assert.match(elevatorArt(v.art),/viewBox="0 0 340 210"/);assert.ok(v.text.replace(/(.{1,43})(?:\s|$)/g,'$1\n').trim().split('\n').length<=7,v.text);}}for(const stages of elevatorStages)assert.equal(new Set(stages.map(elevatorArt)).size,stages.length);});
test('floor exploration controls and the new adventure portal are reachable and distinct from construction',()=>{assert.equal(objects.find(o=>o.id==='grounds-elevator').kind,'construction');assert.equal(objects.find(o=>o.id==='grounds-elevator-adventure').elevatorEntry,true);for(const o of objects.filter(o=>o.zone==='elevator'))assert.ok(pathfind(zones.elevator.spawn,[o.x-65,o.y+55],'elevator').length,o.id);assert.equal(new Set(objects.map(o=>o.id)).size,objects.length);});
test('journal records actual rescues and finale with floor context for revisiting',()=>{assert.equal(getJournalEntries('adventures',new Set(),new Set(),objects,materials,{}, {},{}, {},normalizeElevator()).length,0);const records=getJournalEntries('adventures',new Set(),new Set(),objects,materials,{}, {},{}, {},finished());assert.equal(records.length,7);assert.equal(records[2].elevatorDeck,2);assert.equal(records[6].elevatorDeck,6);assert.match(records[6].fact,/tick ship/);});
